def dc4_dt(tau, c4, c1, c2, c3):
    s1 = 2
    k1 = A1 * math.exp(-E1 / (R * T))
    result = k1 * s1 * c1*c2*c3 - (1/tau)*c4
    return result

def dc1_dt(tau, c1, c2, c3, c5, T):
    s13 = 1
    k1 = A1 * math.exp(-E1 / (R * T))
    k2 = A2 * math.exp(-E2 / (R * T))
    k3 = A3 * math.exp(-E3 / (R * T))
    result = -k1 * 2 * c1 * c2 - k2 * 1 * c1 * c5 - k3 * 2 * c1 * c3 + (1 / tau) * (c1)
    return result


def dc2_dt(tau, c1, c2, T):
    k1 = A1 * math.exp(-E1 / (R * T))
    k4 = A4 * math.exp(-E4 / (R * T))
    c2_in = C_NH3_vx
    result = -k1 * 2 * c1 * c2 - k4 * 4 * c1 * c2 + (1 / tau) * (c2_in - c2)
    return result


def dc3_dt(tau, c1, c2, c3, T):
    s3 = 2
    k1 = A1 * math.exp(-E1 / (R * T))
    result = k1 * s3 * c1 * c2 + (1 / tau) * -c3
    return result


def find_c3(V_cur, T_cur, e=0.01, return_as_list=False, v_list=[]):
    c1_n1 = (C_1_in * ro) / (100 * m_c1)
    c2_n1 = (C_2_in * ro) / (100 * m_c2)
    c3_n1 = 0
    # fig, axs = plt.subplots(3)
    # ax = axs[0]
    # ax_2 = axs[1]
    # ax_3 = axs[2]

    tau = V_cur / v
    count = 0
    c1_list = [c1_n1]
    c2_list = [c2_n1]
    c3_list = [c3_n1]
    while True:
        count += 1
        if not return_as_list:
            tau = V_cur / v_list[count - 1]
        c1_n2 = c1_n1 + 0.1 * dc1_dt(tau, c1_n1, c2_n1, T_cur)
        c2_n2 = c2_n1 + 0.1 * dc2_dt(tau, c1_n1, c2_n1, T_cur)
        c3_n2 = c3_n1 + 0.1 * dc3_dt(tau, c1_n2, c2_n2, c3_n1, T_cur)
        if abs(c3_n2 - c3_n1) < e:
            c3_list.append(c3_n1)
            c2_list.append(c2_n1)
            c1_list.append(c1_n1)
            break
        c1_n1 = c1_n2
        c2_n1 = c2_n2
        c3_n1 = c3_n2
        c3_list.append(c3_n1)
        c2_list.append(c2_n1)
        c1_list.append(c1_n1)

    t = np.arange(0, count + 1)
    if return_as_list:
        return c3_list, t
    return c3_n1


def norm(x_cur, x_max, x_min):
    return (x_cur - x_min) / (x_max - x_min)


def denorm(x_norm, x_max, x_min):
    return x_norm * (x_max - x_min) + x_min


